execution.command:
RUN_ID="${LONGCOT_MINI_RUN_ID:-longcot_mini_re4_$(date -u +%Y%m%dT%H%M%SZ)}"; OUT_DIR="data/longcot_mini_calibration/${RUN_ID}"; mkdir -p "${OUT_DIR}"; .venv/bin/python scripts/benchmark/longcot_mini_stack_runner.py --run-id "${RUN_ID}" --role-ports frontdoor=8080,8180,8280,8380 --role-ports worker_general=8082,8182,8282,8382 --endpoint chat --max-tokens "${LONGCOT_MINI_MAX_TOKENS:-2048}" --timeout "${LONGCOT_MINI_TIMEOUT_S:-900}" --summary-out "${OUT_DIR}/stack_runner_summary.json" && for result in benchmarks/results/runs/"${RUN_ID}"/frontdoor_*.json benchmarks/results/runs/"${RUN_ID}"/worker_general_*.json; do
  test -f "${result}" || { echo "missing LongCoT-Mini result files for ${RUN_ID}" >&2; exit 2; };
  stem="$(basename "${result}" .json)";
  .venv/bin/python scripts/benchmark/score_longcot_run.py "${result}"
  --output "${OUT_DIR}/${stem}_score.json";
done
